/**
 * Логотип X-Lance.ai — векторы из макета Figma (DocHub → Kit X-Lance → «Logo X-Lance»).
 * Синие части берут цвет из --c-logo-ink (в тёмной теме — белые), зелёные — Accent green.
 */
type Size = 'xs' | 'sm' | 'md' | 'lg';

interface XlanceLogoProps {
  size?: Size;
  href?: string;
  className?: string;
  iconOnly?: boolean;
  hideIconVariant?: boolean;
}

/** Мини-замена clsx: склеивает классы, отбрасывая false/null/undefined. */
const cx = (...parts: Array<string | false | null | undefined>) =>
  parts.filter(Boolean).join(' ');

const SIZE: Record<Size, string> = {
  xs: 'h-[1.125rem]', // как в меню X-Lance: логотип ~125px в ширину
  sm: 'h-6',
  md: 'h-7',
  lg: 'h-10',
};

const INK = 'var(--c-logo-ink)';
const GREEN = 'var(--c-accent)';

