function Mark() {
  return (
    <>
      <path d={MARK_LOWER} fill={GREEN} />
      <path d={MARK_STROKE} fill={INK} />
      <circle cx="26" cy="14.5" r="6" fill={GREEN} />
    </>
  );
}

export function XlanceLogo({
  size = 'md',
  href = '/',
  className,
  iconOnly = false,
}: XlanceLogoProps) {
  return (
    <a
      href={href}
      aria-label="X-Lance — на главную"
      className={cx(
        'flex shrink-0 items-center rounded-md outline-none',
        'focus-visible:ring-2 focus-visible:ring-brand/40',
        className,
      )}
    >
      <svg
        viewBox={iconOnly ? '0 8 35 27' : '0 8 193 28'}
        fill="none"
        role="img"
        aria-label="X-Lance.ai"
        xmlns="http://www.w3.org/2000/svg"
        className={cx('w-auto shrink-0', SIZE[size])}
      >
        <Mark />
        {!iconOnly && (
          <>
            <path d={WORD_LANCE} fill={INK} />
            <path d={WORD_AI} fill={GREEN} />
          </>
        )}
      </svg>
    </a>
  );
}

export default XlanceLogo;
